class TreeNode:
    # Represents a node in the BST
    def __init__(self, key):
        self.key = key          # Value stored in the node
        self.left = None        # Left child
        self.right = None       # Right child


class BinarySearchTree:
    # Binary Search Tree with insert, find and in-order traversal
    def __init__(self):
        self.root = None        # Root of the tree, None if empty

    def insert(self, key):
        # Public insert method, creates new node if tree is empty
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_recursive(self.root, key)

    def _insert_recursive(self, node, key):
        # Recursively insert key respecting BST property
        if key < node.key:
            # Go to left subtree
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_recursive(node.left, key)
        elif key > node.key:
            # Go to right subtree
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_recursive(node.right, key)
        else:
            # Duplicate keys are ignored
            pass

    def find(self, key):
        # Public find method, returns True if key exists
        return self._find_recursive(self.root, key)

    def _find_recursive(self, node, key):
        # Recursively search for key
        if node is None:
            return False
        if key == node.key:
            return True
        elif key < node.key:
            return self._find_recursive(node.left, key)
        else:
            return self._find_recursive(node.right, key)

    def inorder_traversal(self):
        # Public in-order traversal, returns list of keys in sorted order
        result = []
        self._inorder_recursive(self.root, result)
        return result

    def _inorder_recursive(self, node, result):
        # In-order: left, root, right
        if node is not None:
            self._inorder_recursive(node.left, result)  # Visit left subtree
            result.append(node.key)                     # Visit node
            self._inorder_recursive(node.right, result) # Visit right subtree
